import java.util.*;

public class Main {
    int largestRectangleArea(int[] heights) {
        Deque<Integer> stack = new ArrayDeque<>();                                   // a monotonic INCREASING stack of bar indices, awaiting their right boundary
        int maxArea = 0;
        for (int i = 0; i <= heights.length; i++) {
            int h = (i == heights.length) ? 0 : heights[i];                             // a virtual 0-height bar at the end forces everything to resolve
            while (!stack.isEmpty() && heights[stack.peek()] >= h) {
                int height = heights[stack.pop()];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;                     // bounded by the new stack top (or the true start, if now empty)
                maxArea = Math.max(maxArea, height * width);
            }
            stack.push(i);
        }
        return maxArea;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] heights = {2, 1, 5, 6, 2, 3};
        System.out.println(solution.largestRectangleArea(heights));
    }
}

